 function top(){root.innerHTML=`<div class="sx-main"><div class="sx-date-controls">${dates()}<div class="sx-searchbox" data-sx-searchbox hidden>${I('search')}<input data-sx-query placeholder="Search service, route, vehicle" value="${E(S.search)}"><button class="sx-iconbtn" data-sx-find>${I('x')}</button></div><div class="sx-calendar-popup" data-sx-calendar-popup hidden><label>Go to date <input type="date" value="${E(S.selectedDate)}" data-sx-jump-date></label><button type="button" data-sx-jump-go>Go</button><button type="button" data-sx-jump-today>Today</button></div></div><div data-sx-list></div></div>`;drawList()}
