 async function refresh(){const query={from:S.date,to:addDays(S.date,6)};if(S.filterFrom)query.from_city_id=S.filterFrom;if(S.filterTo)query.to_city_id=S.filterTo;const d=await G.get('/schedules?'+G.qs(query));S.list=d.schedules||[];drawList()}
