 function seatColor(s){if(S.selectedSeats.has(s.code))return 'selected';if(s.status==='blocked')return 'blocked';if(s.status==='hold')return 'hold';if(s.status==='no_show')return 'no-show';if(['booked','booked_female','female'].includes(s.status)&&((s.booking?.gender||'').toLowerCase().startsWith('f')||['female','booked_female'].includes(s.status)))return 'female';if(['booked','booked_male','male'].includes(s.status)||s.booking)return 'male';return 'available'}
 function seatsGraphic(){if(window.ScheduleManageV48&&S.tab==='bookings')return ScheduleManageV48.seatDiagram(S);if(!S.map)return `<div class="sx-empty">Seat inventory unavailable for this segment.</div>`;
 return `<div class="sx-seat-diagram">${S.map.decks.map(deck=>`<div class="sx-deck"><div class="sx-deck-head"><b>${E(deck.deck)}</b>${deck.deck.toLowerCase()==='lower'?'<span class="sx-wheel" title="Driver position"><svg class="st-steering-svg" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 48" fill="none" aria-hidden="true"><circle cx="24" cy="24" r="21" fill="#0c2855" stroke="#f8fbff" stroke-width="2"/><circle cx="24" cy="24" r="18" stroke="#318aff" stroke-width="3"/><circle cx="24" cy="24" r="6" fill="#216be9" stroke="#e5f4ff" stroke-width="2"/><path d="M24 18 21 6 M29 26l13 9M19 27 6 35" stroke="#e9f1ff" stroke-linecap="round" stroke-width="5"/><circle cx="24" cy="24" r="3" fill="#7ad3ff"/></svg></span>':''}</div><div class="sx-deck-grid" style="grid-template-columns:repeat(${Math.max(1,N(deck.cols))},minmax(28px,1fr));grid-template-rows:repeat(${Math.max(1,N(deck.rows))},32px)">${deck.seats.map(s=>`<button type="button" class="sx-seat sx-${seatColor(s)} ${S.selectedSeats.has(s.code)?'sx-chosen':''}" data-sx-seat="${E(s.code)}" style="grid-column:${N(s.col)+1}/span ${Math.max(1,N(s.w)||1)};grid-row:${N(s.row)+1}/span ${Math.max(1,N(s.h)||1)}" title="${E(s.code)} • ${E(s.status)} • ${INR(s.fare)}"><span class="sx-seat-fare">${E(N(s.fare)?Math.round(N(s.fare)):'—')}</span><strong>${E(s.code)}</strong>${s.booking?`<small>×1</small>`:''}</button>`).join('')}</div><div class="sx-deck-footer">${I('arrowDown',14)} <span>Door</span></div></div>`).join('')}</div>`}
 const stationBtns=()=>`<div class="sx-station-tools">${[['stations','Stations','map'],['pickups','Pickups','arrowUp'],['drops','Drops','arrowDown'],['bookedby','Booked by','credit'],['bookings','Bookings','file']].map(([key,label,ico])=>`<button data-sx-summary="${key}">${I(ico,15)}<small>${label}</small></button>`).join('')}</div>`;
 const legend=()=>`<div class="sx-legend">${[['available','Available'],['male','Male (Booked)'],['female','Female (Booked)'],['blocked','Blocked'],['hold','Hold'],['selected','Selected']].map(([t,l])=>`<span><i class="sx-legend-${t}"></i>${l}</span>`).join('')}</div>`;
 function bookingTab(){const all=allSeats();const counts={available:all.filter(s=>s.status==='available').length,booked:all.filter(s=>['booked','booked_male','booked_female','male','female','hold','no_show'].includes(s.status)||!!s.booking).length,blocked:all.filter(s=>s.status==='blocked').length};const cs=S.detail.route?.via_cities||[];return `<div class="sx-book-columns"><section class="sx-book-left"><header class="sx-book-head"><strong>${I('layout')} Seat Layout</strong><div>${bt('copy','Copy','data-sx-copy title="Copy seat layout image" aria-label="Copy current seat layout as PNG image"','mini')}${bt('link','Share','data-sx-share','mini')}</div></header><div class="sx-book-ident">${I('bus',13)} ${E(S.detail.vehicle?.registration_number||'Unassigned vehicle')} <span>${I('user',13)} ${E(S.detail.crew?.[0]?.name||'Crew pending')}</span><span>${E(S.detail.service_number)}</span></div><div class="sx-book-location">${I('pin',13)} ${E(S.trip?.position?.address||'No verified live position')} <small>${S.trip?.position?.updated_at?fdt(S.trip.position.updated_at):''}</small></div>${stationBtns()}<div class="sx-journey-select"><label>${I('pin',12)} From <select data-sx-fromcity>${cs.slice(0,-1).map(c=>`<option value="${E(c.city_id)}" ${String(c.city_id)===String(S.cityFrom)?'selected':''}>${E(c.name)}</option>`).join('')}</select></label><span>→</span><label>To <select data-sx-tocity>${cs.slice(1).map(c=>`<option value="${E(c.city_id)}" ${String(c.city_id)===String(S.cityTo)?'selected':''}>${E(c.name)}</option>`).join('')}</select></label></div><div class="sx-seat-scroll">${seatsGraphic()}</div>${legend()}<div class="sx-seat-bottom">${bt('pin','Location','data-sx-location','mini')}${bt('clock','Timings','data-sx-timings','mini')}${bt('clock','Delay','data-sx-delay','mini')}${bt('bell','Notify','data-sx-notify-pop','mini')}${bt('shield','Hide fares','data-sx-hidefares','mini')}${bt('rupee','Print','data-sx-print','mini')}</div></section><section class="sx-book-right">${S.tab==='block'?blockPanel(counts):pickupPanel(counts)}</section></div>`}
 function blockPanel(counts){return `<header class="sx-side-top">${I('shield')} Block <span class="sx-muted">(${counts.blocked} blocked)</span></header><div class="sx-block-hint"><h3>${S.selectedSeats.size?'Selected seats: '+[...S.selectedSeats].join(', '):'Select seats from the layout below'}</h3><p>Click seats to block or unblock them. Only available or already blocked seats may be changed.</p></div><div class="sx-control-grid">${input('Reason','reason',S.draft.blockReason||'Operator quota')}${select('Restriction','gender',['Any','Male','Female'],S.draft.blockGender||'Any')}</div>${bt('shield','Block selected seats','data-sx-block="block"','primary')}${bt('check','Unblock selected seats','data-sx-block="unblock"')}${bt('refresh','Follow route blocks','data-sx-block="follow_route"')}${previewNote('Seat block changes use the existing authorized schedule API after confirmation.')}`}
 function groupPeople(){const passengers=(S.trip?.passengers||[]).filter(p=>p.status!=='cancelled');const src=S.group;const map=new Map();for(const p of passengers){const key=src==='Pickup'?p.boarding?.name||'Not assigned':src==='Drop'?p.dropping?.name||'Not assigned':src==='City'?p.from||'Unknown city':src==='Source'?p.source||'Unknown':src==='Booked On'?(p.booked_at||'Unknown date'):src==='Fare'?INR(p.fare):src==='Trips'?String(p.trips||0):'All passengers';if(!map.has(key))map.set(key,[]);map.get(key).push(p)}return [...map.entries()]}
 function pickupPanel(counts){const sel=S.selectedPnrs.size;return `<div class="sx-side-top"><button data-sx-side="pickup" class="${S.side==='pickup'?'active':''}">${I('pin',14)} Pickup Chart</button><button data-sx-side="history" class="${S.side==='history'?'active':''}">${I('history',14)} History</button></div>${S.side==='history'?timeline():`<div class="sx-side-stats"><span class="sx-green">● Available ${counts.available}</span><span class="sx-red">● Booked ${counts.booked}</span><span>● Blocked ${counts.blocked}</span></div><div class="sx-side-actions">${bt('print','Print Pickup Chart','data-sx-print','blue')}${bt('upload','Import Pickup Chart','data-sx-import')}${bt('x','Cancel ('+sel+')','data-sx-cancel-selected')}${bt('bell','Notify ('+sel+')','data-sx-notify-pop')}</div><div class="sx-group"><button data-sx-group="Pickup" class="${S.group==='Pickup'?'on':''}">${I('pin',13)} History</button><label>Group by:</label>${['Pickup','Drop','City','Source','Booked On','Fare','Trips'].map(g=>`<button data-sx-group="${E(g)}" class="${S.group===g?'on':''}">${E(g)}</button>`).join('')}</div><div class="sx-pnr-select"><label><input type="checkbox" data-sx-allpnrs ${sel&&sel===new Set((S.trip?.passengers||[]).map(x=>x.pnr)).size?'checked':''}> ${sel} of ${(S.trip?.passengers||[]).length} selected</label><button data-sx-select-all> Select All</button><button data-sx-clear>Clear</button><input data-sx-people-search placeholder="Search passenger / PNR / seat" value="${E(S.sideSearch)}"></div><div class="sx-groups-list">${groupPeople().map(([group,ps],i)=>`<details class="sx-person-group" open><summary><span class="sx-circle">${i+1}</span><b>${E(group)}</b><span>${ps.length} seat(s)</span><span class="sx-muted">${E(ps[0]?.boarding?.time?formatTime(ps[0].boarding.time):'')}</span>${I('chevron')}</summary>${ps.filter(p=>!S.sideSearch||[p.name,p.pnr,p.seat,p.phone].join(' ').toLowerCase().includes(S.sideSearch.toLowerCase())).map(p=>`<div class="sx-person"><input data-sx-selectpnr="${E(p.pnr)}" type="checkbox" ${S.selectedPnrs.has(String(p.pnr))?'checked':''}><span class="sx-number">${E(p.seat)}</span><div><b>${E(p.name)}</b><small>${I('phone',11)} ${E(p.phone||'')}　${E(p.pnr)}　${E(p.source||'')}</small><small>${E(p.from||'')} → ${E(p.to||'')}</small></div><span class="sx-pill">${E(p.status||'')}</span><button class="sx-iconbtn" data-sx-pnr="${E(p.pnr)}" title="Open ticket">${I('eye')}</button></div>`).join('')}</details>`).join('')||'<div class="sx-empty">No passenger records for this trip.</div>'}</div>`}`}
 function timeline(){const hist=S.history||[];return `<div class="sx-timeline"><p class="sx-muted">${hist.length} booking record(s) — confirmed, held, cancelled and expired</p><div class="sx-timeline-badges"><span>All ${hist.length}</span><span>Seat blocks ${N(S.detail.seat_blocks?.length)}</span><span>Bookings ${hist.filter(b=>b.status==='confirmed').length}</span></div>${hist.slice(0,70).map(b=>`<article><span class="sx-timeline-dot"></span><div><b>${E(b.source||'Booking')} · PNR ${E(b.pnr)}</b><small>${E(b.contact_name)} · ${E(b.passengers?.map(p=>p.seat).join(', '))} · ${E(b.status)}</small><small>${E(b.blocked_at?fdt(b.blocked_at):'')}</small></div><button data-sx-pnr="${E(b.pnr)}">${I('eye')}</button></article>`).join('')||'<div class="sx-empty">No booking history</div>'}</div>`}
 async function updateTab(){if(window.ScheduleUpdateV51)return ScheduleUpdateV51.render(S,G);const d=S.detail;let vehicles=[],staff=[];try{const v=await G.get('/vehicles');vehicles=v.vehicles||[]}catch(_){}try{const r=await G.get('/staff?status=all');staff=r.staff||[]}catch(_){}S.vehicles=vehicles;S.staff=staff;const crew=d.crew||[];const vehicleOptions=vehicles.map(v=>[v.id,v.registration_number]);const staffOptions=staff.map(v=>[v.id,v.name]);return `<div class="sx-update-shell"><section class="sx-trip-banner"><b>${I('bus')} ${E(d.service_number)} <span class="sx-pill green">${E(d.status||'ACTIVE')}</span></b><strong>${E(d.origin)} → ${E(d.destination)}</strong><span>${I('calendar',14)} ${safeDate(d.travel_date)}</span><span>${I('clock',14)} ${formatTime(d.departure_time)} – ${formatTime(d.arrival_time)}</span><span>${E(d.coach||'No coach')}</span><div>${E(d.seats_booked)}/${E(d.capacity)} · ${Math.round(N(d.occupancy_pct))}%</div></section>
 <section class="sx-light-card"><header><b>${I('bus')} Vehicle & Staff Assignment</b>${bt('edit','Edit','data-sx-editassign')}</header><p class="sx-muted">${I('link',12)} Data Source: ${E(d.sync_with_route!==false?'Route':'Schedule override')}</p><div class="sx-assignment-preview"><div class="sx-assigned-vehicle"><b>VEHICLE</b><span>${I('bus')} ${E(d.vehicle?.registration_number||'Not assigned')}</span></div><div class="sx-assigned-staff"><b>STAFF</b><div class="sx-crew-cards">${crew.map(c=>`<div><span>${I('user',14)} ${E(c.role||'Staff')}</span><strong>${E(c.name||'—')}</strong><small>${I('phone',13)} ${E(c.phone||'')}</small></div>`).join('')||'No crew assigned'}</div></div></div><div data-sx-assignment-form hidden><form data-sx-assign-form><div class="sx-control-grid">${select('Vehicle','vehicle_id',[['','Unassigned'],...vehicleOptions],d.vehicle?.id)}</div><div class="sx-crew-edit" data-sx-crewrows>${crew.map((c,i)=>crewRow(c,i,staffOptions)).join('')}</div>${bt('plus','Add Staff','data-sx-addcrew')}${bt('check','Update Assignment','data-sx-submitassign','primary')}</form></div></section>
 <section class="sx-light-card"><header><b>${I('phone')} CALL ROUTING</b><small>Data Source: Schedule</small></header><div class="sx-switch-grid">${[['cloud','Cloud Calling',true],['mask','Passenger Number Masking',true],['vehicle','Direct to Vehicle',true],['gps','Driver Mobile GPS',false]].map(([k,l,v])=>`<label class="sx-toggle-row">${I(k==='gps'?'pin':'phone',15)} ${l}<span class="sx-spacer"></span><input type="checkbox" data-sx-draft-toggle="${k}" ${S.draft[k]===undefined?v?'checked':'':S.draft[k]?'checked':''}><span class="sx-switch-visual"></span></label>`).join('')}</div>${input('Escalation contacts','escalation',S.draft.escalation||'')}</section>
 <section class="sx-light-card"><header><b>${I('bus')} AUTOS & CABS</b><small>Data Source: Route</small></header><div class="sx-toggle-row"><span>Ride to boarding point / from drop</span><div class="sx-segment">${['Off','Pickups','Drops','Both'].map(x=>`<button data-sx-cabs="${x}" class="${(S.draft.cabs||'Drops')===x?'active':''}">${x}</button>`).join('')}</div></div></section>
 <section class="sx-light-card"><header><b>${I('file')} Schedule Details</b></header><div class="sx-schedule-fields"><span>${I('bus',13)} SERVICE NO.<b>${E(d.service_number)}</b></span><span>${I('pin',13)} NAME<b>${E(d.service_name||'')}</b></span><span>${I('bus',13)} COACH TYPE<b>${E(d.coach||'')}</b></span>${bt('refresh','Coach Transfer','data-sx-coach-transfer','mini')}</div></section>
 <section class="sx-light-card"><header><b>${I('refresh')} Sync with Route</b><label class="sx-switch"><input data-sx-sync type="checkbox" ${d.sync_with_route!==false?'checked':''}><span></span></label></header><p>Route changes (coach, timings, stages, fares) will apply to this schedule when synchronization is enabled.</p><label class="sx-check"><input type="checkbox" data-sx-missing-ota ${S.draft.missing_ota?'checked':''}> Missing on RedBus / AbhiBus? Tick this and Sync to re-push this trip's seats.</label>${bt('refresh','Sync with OTAs','data-sx-sync-ota','outline')}${previewNote('Cloud calling, GPS, cabs and OTA sync are UI previews; their server configuration endpoints are not connected.')}</section></div>`}
 function crewRow(c,i,staffOpts){return `<div class="sx-crew-row" data-sx-crewrow="${i}"><select name="role">${['Driver','Helper','Conductor','Attendant','Pickup Van'].map(r=>`<option ${r===(c.role||'Driver')?'selected':''}>${r}</option>`).join('')}</select><select name="staff_id"><option value="">Select staff</option>${staffOpts.map(([id,name])=>`<option value="${E(id)}" ${String(c.staff_id)===String(id)?'selected':''}>${E(name)}</option>`).join('')}</select><input name="phone" placeholder="Phone" value="${E(c.phone||'')}"><button type="button" data-sx-crewremove title="Remove staff">${I('trash',16)}</button></div>`}
 function citiesTab(){const d=S.detail;const cities=d.route?.via_cities||[],pairs=[];for(let i=0;i<cities.length-1;i++)for(let j=i+1;j<cities.length;j++)pairs.push([cities[i],cities[j]]);const delay=N(S.draft.delay_min??d.delay_minutes??0),hours=Math.floor(Math.abs(delay)/60),mins=Math.abs(delay)%60;return `<div class="sx-cities-editor sx48-cities"><div class="sx-source-chip">${I('link',12)} Data Source: Route</div><div class="sx-time-shift sx48-adjust"><b>Adjust Trip Time</b><div class="sx-segment">${['Delay','Advance'].map(x=>`<button data-sx-shift-direction="${x}" class="${(S.draft.shift_dir||'Delay')===x?'active':''}">${x}</button>`).join('')}</div><label><input type="number" name="delay_hr" value="${hours}" min="0" max="12" aria-label="Delay hours"><span>h</span></label><label><input type="number" name="delay_min" value="${String(mins).padStart(2,'0')}" min="0" max="59" aria-label="Delay minutes"><span>m</span></label>${bt('clock','Apply delay','data-sx-applydelay','primary')}<p>Applies as soon as you press it — it does not wait for Save. Only unreached stops will move. Changes to the route template are not made.</p></div><div class="sx-two-card sx48-city-endpoints"><div class="sx-origin"><span class="sx48-city-symbol">${I('pin',24)}</span><div><small>ORIGIN</small><h3>${E(d.origin)}</h3><p>${E(cities[0]?.state||'')} <span class="sx48-daychip">Day ${E(cities[0]?.day||1)} · ${E(formatTime(d.departure_time))}</span></p></div></div><div class="sx-destination"><span class="sx48-city-symbol">${I('pin',24)}</span><div><small>DESTINATION</small><h3>${E(d.destination)}</h3><p>${E(cities[cities.length-1]?.state||'')} <span class="sx48-daychip">Day ${E(cities[cities.length-1]?.day||d.arrival_day_offset+1||1)} · ${E(formatTime(d.arrival_time))}</span></p></div></div></div><section class="sx-light-card"><header><b>${I('pin')} Via Cities <span>${Math.max(0,cities.length-2)}</span></b></header>${table(['STATE','CITY','DAY','TIME','ORIGIN','DESTINATION'],cities.slice(1,-1).map((c,i)=>`<tr><td>${E(c.state||'—')}</td><td>${I('pin',12)} ${E(c.name)}</td><td><span class="sx-pill">${E(c.day||2)}</span></td><td>${formatTime(c.time)}</td><td><label class="sx-switch sx-small"><input data-sx-via="${E(c.city_id)}|origin" type="checkbox" ${S.draft.via_city_enabled?.[c.city_id]?.origin===false?'':'checked'}><span></span></label></td><td><label class="sx-switch sx-small"><input data-sx-via="${E(c.city_id)}|destination" type="checkbox" ${S.draft.via_city_enabled?.[c.city_id]?.destination===false?'':'checked'}><span></span></label></td></tr>`),'No via cities')}</section><section class="sx-light-card sx48-route-pairs"><header><b>${I('map')} Routes <span class="sx48-combination-count">${pairs.length} city pairs</span></b><button data-sx-add-subroute>${I('plus')} Add sub-route</button></header>${table(['ROUTE / SLOT ID','ORIGIN → DESTINATION','TIMING','FARE %','ACTIONS'],pairs.map(([a,b],i)=>`<tr><td><small>${i===0?E(d.route?.id||d.route_id):'—'}</small><span class="sx48-route-kind">${i===0?'MAIN-ROUTE':'SUB-ROUTE · preview'}</span></td><td>${E(a.name)} → ${E(b.name)}</td><td><span class="sx-pill">${formatTime(a.time||d.departure_time)} → ${formatTime(b.time||d.arrival_time)}</span></td><td><input class="sx-short" type="number" data-sx-subrate="${i}" value="${E(S.draft.rates?.[i]??(i===0?100:99))}" min="0" max="100"></td><td>${i?`<button data-sx-remove-subroute="${i}">${I('trash')}</button>`:'—'}</td></tr>`))}</section>${previewNote('Via-city toggles and proposed fare percentages are saved as schedule preferences only. Published city-pair routes and fares must be managed in authorized Routes/Fares workflows. No synthetic sub-route ID is published.')}</div>`}
 function stopTab(){const kind=S.tab==='pickups'?'pickup':'drop',d=S.detail;const stages=(d.route?.stages||[]).filter(s=>s.type===kind).map(s=>({...s,...(S.draft.stopChanges?.[s.id]||{})})).sort((a,b)=>(N(a.day)-N(b.day))||String(a.time).localeCompare(String(b.time)));const cityNames=[...new Set(stages.map(s=>s.city_name||s.city||d.route?.via_cities?.find(c=>String(c.city_id)===String(s.city_id))?.name||'Other'))];const active=S.stopCity&&cityNames.includes(S.stopCity)?S.stopCity:cityNames[0]||'';const byCity=s=>s.city_name||s.city||d.route?.via_cities?.find(c=>String(c.city_id)===String(s.city_id))?.name||'Other';const shown=stages.filter(s=>byCity(s)===active);return `<div class="sx-stops-ui"><div class="sx-stop-header"><div><small>${I('link',11)} Data Source: Route</small><h3>${kind==='pickup'?'Pickup':'Drop-off'} Points</h3></div>${bt('edit','Edit','data-sx-editstops','outline')}</div><div class="sx-stop-cities">${cityNames.map(c=>`<button data-sx-stopcity="${E(c)}" class="${c===active?'on':''}">${E(c)} <small>${stages.filter(s=>byCity(s)===c).length}</small></button>`).join('')}</div><div class="sx-stop-cards">${shown.map((s,i)=>{const phone=s.contact_number||'';const lat=s.lat??s.latitude,lng=s.lng??s.longitude;const pax=(S.trip?.passengers||[]).filter(p=>p[kind==='pickup'?'boarding':'dropping']?.id===s.id&&p.status!=='cancelled').length;return `<article class="sx-stop-card"><span class="sx-stop-time">${formatTime(s.time)} ${Number(s.day||1)>1?`<small>DAY ${E(s.day)}</small>`:''}</span><div class="sx-stop-content"><div class="sx-stop-name"><span class="sx-circle">${i+1}</span><b>${E(s.name)}</b>${s.is_primary||s.primary?'<span class="sx-badge-purple">★ Primary</span>':''}</div>${s.pickup_type==='metro'||/metro/i.test(s.name)?`<span class="sx-metro">${I('bus',13)} Free metro Pickup</span>`:''}<p>${E(s.landmark||s.address||'')}</p><span class="sx-stop-type">${I('pin',14)} ${E(s.pickup_type||'Bus Stop')}</span>${phone?`<a href="tel:${E(phone)}" class="sx-stop-phone">${I('phone',13)} ${E(phone)}</a>`:''}${lat!=null&&lng!=null?`<a href="https://www.google.com/maps?q=${E(lat)},${E(lng)}" target="_blank" rel="noopener" class="sx-stop-coords">${I('pin',13)} ${E(lat)}, ${E(lng)}</a>`:''}<div class="sx-stop-count"><span>${pax} passengers</span>${bt('edit','Edit','data-sx-editstop="'+E(s.id)+'"','mini')}</div></div></article>`}).join('')||'<div class="sx-empty">No '+kind+' stops for this city.</div>'}</div>${previewNote('Stop pin and arrival-time corrections need verified GPS halt evidence. Changes in this screen remain preview-only.')}</div>`}
 async function faresTab(){if(!S.fares)S.fares=await G.get(`/schedules/${sd()}/fares`);const f=S.fares;const ds=S.draft;const seats=allSeats();const groups=new Map();for(const s of seats){const type=/^[0-9]+[LU]$/.test(s.code)?(String(s.code).endsWith('U')&&N(s.col)>0?'DUB':'SLB'):/^[0-9]+$/.test(s.code)?'SS':String(s.type||'OTHER').toUpperCase();if(!groups.has(type))groups.set(type,[]);groups.get(type).push(s)}const rows=[...groups.entries()];const cs=S.detail.route.via_cities||[];const fopts=cs.slice(0,-1).map(x=>[x.city_id,x.name]);const topts=cs.slice(1).map(x=>[x.city_id,x.name]);const price=(g)=>{const fa=(f.fares||[]).find(x=>String(x.from_city_id)===String(S.cityFrom)&&String(x.to_city_id)===String(S.cityTo))||(f.fares||[])[0]||{};return g==='SS'?fa.seater||0:g==='SLB'?fa.sleeper_lower||0:fa.sleeper_upper||0};return `<div class="sx-fares-ui"><div class="sx-pricing-top"><div class="sx-pricing-mode"><b>${I('spark',21)} Auto Pricing</b><p>AI sets fares for this trip.</p><label class="sx-switch"><input data-sx-draft-toggle="auto_price" type="checkbox" ${ds.auto_price?'checked':''}><span></span></label></div><div class="sx-pricing-guard"><b>PRICE GUARD RAILS</b><div>${input('Min ₹','min_price',ds.min_price??f.auto_pricing?.min??650,'number')}${input('Max ₹','max_price',ds.max_price??f.auto_pricing?.max??4500,'number')}</div><small>AI never prices a seat below Min or above Max.</small></div><div class="sx-pricing-curve">${select('DEMAND CURVE','curve',['Max revenue','Balanced','Max occupancy'],ds.curve||'Max revenue')}<small>Targets: <b>${(ds.curve||'Max revenue')==='Max revenue'?'Revenue':ds.curve||'Revenue'}</b></small><div class="sx-targets">${[['7D','5%'],['3D','10%'],['1D','35%'],['12H','40%'],['6H','45%'],['TRIP','100%']].map(x=>`<div><small>${x[0]}</small><strong>${x[1]}</strong></div>`).join('')}</div></div></div><div class="sx-fare-last">Last change: <b>${f.auto_price?.at?fdt(f.auto_price.at):'No trip override'}</b> · Fares ${f.synced?'follow route':'custom trip prices'} · Recommended changes are not applied automatically.</div><div class="sx-fare-route"><span>${I('pin',13)} Fares for</span><label>From <select data-sx-fromcity>${fopts.map(([v,n])=>`<option value="${E(v)}" ${String(S.cityFrom)===String(v)?'selected':''}>${E(n)}</option>`).join('')}</select></label><label>To <select data-sx-tocity>${topts.map(([v,n])=>`<option value="${E(v)}" ${String(S.cityTo)===String(v)?'selected':''}>${E(n)}</option>`).join('')}</select><span class="sx-pill">Main route</span></div><div class="sx-fare-controlbar"><span>${f.fares?.length||0} route(s)</span>${bt('rupee','Set Rate','data-sx-fare-mode="set"')}${bt('edit','CHANGE','data-sx-fare-mode="change"')}${bt('rupee','Fixed ₹','data-sx-farekind="fixed"','active')}${bt('chart','Percent %','data-sx-farekind="percent"')}${bt('minus','','data-sx-faredelta="-10"','mini')}<input data-sx-delta type="number" value="${E(ds.fare_delta||0)}">${bt('plus','','data-sx-faredelta="10"','mini')}<div class="sx-weekdays">${['All',...weekday].map(x=>`<button data-sx-weekday="${x}" class="${x==='All'?'active':''}">${x}</button>`).join('')}</div></div><div class="sx-fare-flex"><div class="sx-faregroup-table">${table(['','NAME','SEAT ID(S)','NET PRICE','PRICE (₹)','ACTIONS'],rows.map(([g,arr],i)=>`<tr><td><input type="checkbox" checked data-sx-groupcheck="${E(g)}"></td><td><b>${E(g)}</b></td><td><div class="sx-seat-chips">${arr.map(x=>`<span>${E(x.code)}</span>`).join('')}</div></td><td><span class="sx-pill blue">${E(arr.length)} seats</span></td><td><button class="sx-tiny" data-sx-groupminus="${E(g)}">${I('minus')}</button><input class="sx-short" data-sx-groupfare="${E(g)}" value="${E(ds.groupFares?.[g]??price(g))}" type="number" min="0"><button class="sx-tiny" data-sx-groupplus="${E(g)}">${I('plus')}</button></td><td><button class="sx-tiny" data-sx-removefare="${E(g)}">${I('trash')}</button></td></tr>`),'Seat diagram not available')}${bt('plus','Add fare group','data-sx-addgroup')}</div><div class="sx-fare-seatmap"><h4>Seat preview</h4>${seatsGraphic()}</div></div><div class="sx-fare-rules"><h3>Fare rules</h3><p>Charge more for popular seats and less for the ones passengers avoid. Rules can apply to selected seats, days, trips and city pairs.</p><div class="sx-rules-actions">${bt('plus','Premium seats','data-sx-rule-new="premium"')}${bt('minus','Discount seats','data-sx-rule-new="discount"')}${bt('pin','City rule','data-sx-rule-new="city"')}</div>${S.previewRules.map((r,i)=>`<button class="sx-rule-chip" data-sx-rule="${i}">${r.type==='discount'?'−':'+'}${INR(r.amount)} · ${r.seats?.length||0} seats</button>`).join('')}<div class="sx-rule-edit">${input('Name (optional)','rule_name',ds.rule_name||'Rule 1')}${select('Change','rule_direction',['Increase','Decrease'],ds.rule_direction||'Increase')}${input('Amount','rule_amount',ds.rule_amount??100,'number')}${select('Mode','rule_unit',['₹','%'],ds.rule_unit||'₹')}${bt('save','Save fare rules','data-sx-save-rule','primary')}</div>${previewNote('Seat rules and trip fares save to this trip. Auto Pricing settings are managed on the route.')}</div></div>`}
 async function pnlTab(){if(!can('schedules.financial'))return '<div class="sx-empty">Financial reporting permission required</div>';if(!S.pnl)S.pnl=await G.get(`/schedules/${sd()}/pnl`);return window.SchedulePnlV18?SchedulePnlV18.render({p:S.pnl,detail:S.detail,canEdit:can('schedules.financial')}):'<div class="sx-empty">P&L module is not loaded</div>';}
 function pnlContext(){return {api:G,overlay:S.ov,sid:sd(),canEdit:can('schedules.financial'),setPnl:p=>{S.pnl=p},redraw};}
 function historyTab(){const d=S.detail;return `<section class="sx-history-ui"><header><h3>${I('history')} Schedule history</h3><input data-sx-historysearch placeholder="Search PNR, seat, city or name" value="${E(S.historySearch||'')}">${bt('history','Edit history','data-sx-edithistory')}</header><div class="sx-timeline-badges"><span>All ${S.history.length}</span><span>Bookings ${S.history.filter(x=>x.status==='confirmed').length}</span><span>Holds ${S.history.filter(x=>x.status==='hold').length}</span><span>Cancelled ${S.history.filter(x=>x.status==='cancelled').length}</span></div>${table(['PNR','ROUTE','SEATS','FARE','BOOKED BY','SOURCE','BOOKED ON','STATUS'],S.history.filter(b=>!S.historySearch||JSON.stringify(b).toLowerCase().includes(S.historySearch.toLowerCase())).map(b=>`<tr><td><button data-sx-pnr="${E(b.pnr)}" class="sx-link">${E(b.pnr)}</button></td><td>${E(d.origin)} → ${E(d.destination)}</td><td>${E(b.passengers?.map(x=>x.seat).join(', '))}</td><td>${INR(b.total_amount)}</td><td>${E(b.contact_name)}</td><td>${E(b.source)}</td><td>${b.blocked_at?fdt(b.blocked_at):'—'}</td><td>${E(b.status)}</td></tr>`),'No matching booking records')}</section>`}
 function popup(title,body,foot=''){const m=G.modal({title,size:'lg',body:`<div class="sx-quick-popup">${body}</div>`,foot:foot||'<button class="btn" data-sx-popup-close>Close</button>'});m.el.classList.add('sx-popoverlay');m.$('[data-sx-popup-close]')?.addEventListener('click',m.close);return m}
